// Extract key lunar transition details from the incoming API payload with safety checks
const firstItem = $input.first()?.json || {};
const ingressUTC = firstItem.ingress_utc;
const nextSign = firstItem.next_sign || 'Aries';
const currentSign = firstItem.current_sign || 'Pisces';

// Parse the target ingress timestamp or fallback to current time if missing
const ingressTime = ingressUTC ? new Date(ingressUTC) : new Date();
const validIngressTime = isNaN(ingressTime.getTime()) ? new Date() : ingressTime;

// Initial target: 1 hour before ingress
let postTime = new Date(validIngressTime.getTime() - 60 * 60 * 1000);

// --- DOWNTIME & SLEEP PROTECTION LOGIC ---
// Convert postTime to local time elements (Knoxville, TN timezone context)
// Local hour check: Quiet hours are 19:00 (7 PM) through 05:00 (5 AM)
const localHour = parseInt(postTime.toLocaleString('en-US', { timeZone: 'America/New_York', hour: 'numeric', hour12: false }));

// Check if the target notification falls inside your sleep window (7 PM to 5 AM)
const isDuringSleepHours = localHour >= 19 || localHour < 5;

if (isDuringSleepHours) {
    // If it hits during your rest, shift the approval notification to 6:30 PM 
    // on the evening prior, ensuring you can review it before winding down.
    postTime.toLocaleString('en-US', { timeZone: 'America/New_York' });

    // Set to 18:30 (6:30 PM) on the same or previous day depending on the hour
    if (localHour >= 19) {
        postTime.setHours(18, 30, 0, 0);
    } else {
        // If it's early morning hours (before 5 AM), shift back to 6:30 PM the previous night
        postTime.setDate(postTime.getDate() - 1);
        postTime.setHours(18, 30, 0, 0);
    }
}
// -----------------------------------------

// Generate rich blog content
const blogDraft = `As the Moon transitions from ${currentSign} into ${nextSign}, we enter a powerful shift in emotional currents and collective energy. This alignment invites us to reflect on how we ground our inner intuitive realizations into focused, intentional momentum. Explore how this dynamic influences your daily rhythm and emotional landscape as we navigate this celestial threshold together.`;

// Generate expanded Reddit content with a value-add CTA link back to the app
const redditDraft = `Hey r/moondaylive! 🌙 The Moon is officially shifting from ${currentSign} into ${nextSign}.\n\nThis transition brings a fascinating pivot in our collective emotional weather, moving us from the reflective depths into a renewed wave of initiation and drive.\n\nHow are you tracking this energy today? Drop your thoughts below!\n\n*(Not sure where your natal Moon sits for this transit? Head over to https://moondaylive.com to run an extensive personal evaluation.)*`;

// Return structured workflow data containing the calculated resume time and payload labels
return [{
  json: {
    resumeAt: postTime.toISOString(),
    currentSign,
    nextSign,
    ingressUTC: ingressUTC || new Date().toISOString(),
    label: `Moon ${currentSign} → ${nextSign}`,
    hoursUntilIngress: ((validIngressTime - Date.now()) / 1000 / 60 / 60).toFixed(2),
    blog_content: blogDraft, 
    reddit_content: redditDraft
  }
}];
